const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'n/a':Number(v).toFixed(d);
const human=v=>String(v??'').replaceAll('_',' ').replaceAll('-',' ');
const chip=v=>`<span class="chip ${esc(v)}">${esc(human(v))}</span>`;
const shapes={overview:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',findings:'<path d="M12 3 2 20h20L12 3Z"/><path d="M12 9v4m0 3v1"/>',directory:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4m8-4v4M3 10h18m-13 5h3m3 0h3"/>',evaluation:'<path d="M4 3v18h17M8 16v-4m5 4V6m5 10V9"/>',decisions:'<path d="M4 8a9 9 0 1 1-1 9M4 3v5h5m3-1v6l4 2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[k]||shapes.arrow}</svg>`;
const titles={overview:'Overview',findings:'Findings',directory:'Directory',evaluation:'Evaluation',decisions:'Decision history'};
const names={unused_90:'90-day unused',role_whitelist:'Role whitelist',isolation_forest:'Isolation Forest',rules:'Rules, no judge',minus_jev:'Minus judge',minus_context:'Minus context',minus_peers:'Minus peers',full:'EntitleGuard'};
const main=$('#main');let epoch=0,controller,simController,simToken=0,sim=null,proposal=null,overview,toastTimer;
function route(){const [page,query]=location.hash.slice(1).split('?');return {page:page||'overview',...Object.fromEntries(new URLSearchParams(query||''))};}
function href(page,params={}){const q=new URLSearchParams(Object.entries(params).filter(([k,v])=>k!=='page'&&v!=null&&v!==''));return `#${page}${q.size?'?'+q:''}`;}
function go(page,params={}){const h=href(page,params);if(location.hash===h)render();else location.hash=h;}
const caseHref=(id,permission,section='evidence')=>href('findings',{id,permission,section});
async function api(url,options={}){const res=await fetch(url,{signal:controller?.signal,...options});if(!res.ok){let d;try{d=await res.json();}catch{d={detail:res.statusText};}throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail||d));}return res.json();}
const post=(url,data,signal)=>api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),...(signal?{signal}:{})});
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
const heading=(title,copy,actions='')=>`<div class="page-head"><div><h1>${esc(title)}</h1>${copy?`<p>${esc(copy)}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
const report=()=>`<a class="btn" href="/api/export?format=html" target="_blank" rel="noopener">${icon('export')} Export report</a>`;
const empty=(title,copy)=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p><button class="btn" data-reset>Clear filters</button></div>`;
const refreshAction=()=>'<button class="btn primary" type="button" id="refresh-scores">Refresh risk scores</button>';
const assessmentPanel=()=>'<div id="assessment-panel" class="assessment-panel"></div>';
let watchedRun=null,assessmentTimer=0,announceRun=null;
function elapsedLabel(view){const ms=view?.elapsed_ms!=null?Number(view.elapsed_ms):view?.started_at?Math.max(0,Date.now()-Date.parse(view.started_at)):null;if(ms==null||Number.isNaN(ms))return '';const seconds=Math.max(0,Math.round(ms/1000));return seconds<60?`${seconds}s`:`${Math.floor(seconds/60)}m ${seconds%60}s`;}
function assessmentSentence(summary){if(!summary)return '';if(summary.scores_unchanged&&summary.world_unchanged)return 'Scores unchanged. The same evidence produced the same assessment.';if(summary.scores_unchanged)return 'Risk scores are unchanged. Redundant sources were removed from the saved copy; effective access is the same.';const before=summary.initial_counts?.sensitive_excess_grants,after=summary.final_counts?.sensitive_excess_grants;return `Sensitive excess grants ${before??'n/a'} to ${after??'n/a'}. ${summary.applied_count??0} verified removals applied to the saved copy. ${summary.held_count??0} grants stayed, with the reason recorded.`;}
function assessmentMessage(view){if(!view)return '';if(['queued','running','cancelling'].includes(view.status)){const phase=(view.phases||[]).find(row=>row.status==='running');const elapsed=elapsedLabel(view);return `${phase?.label||'Running assessment'}${elapsed?` · ${elapsed}`:''}`;}if(view.status==='succeeded')return assessmentSentence(view.summary);if(view.status==='cancelled')return 'Assessment cancelled before publication. The snapshot was not changed.';if(view.status==='stale')return 'This refresh was discarded because the snapshot changed. Start it again.';if(view.status==='interrupted')return 'Assessment stopped when the console restarted. The snapshot was not changed.';const phase=(view.phases||[]).find(row=>row.status==='failed')||(view.phases||[]).find(row=>row.id===view.phase);return `${phase?.label||'Assessment'} failed. ${view.error||'The saved copy was not published.'}`;}
function visibleAssessment(){if(watchedRun)return watchedRun;const latest=overview?.assessment?.latest;if(latest&&!['queued','running','cancelling'].includes(latest.status))return latest;return overview?.assessment?.active||null;}
async function localJson(url,options={}){const res=await fetch(url,options);let body=null;try{body=await res.json();}catch{body=null;}if(!res.ok){const detail=body?.detail;const error=Error(typeof detail==='string'?detail:detail?.message||res.statusText);error.status=res.status;throw error;}return body;}
function paintAssessment(){const busy=!!(watchedRun&&['queued','running','cancelling'].includes(watchedRun.status));const button=$('#refresh-scores');if(button){button.disabled=busy;button.textContent=busy?'Running assessment':'Refresh risk scores';}const panel=$('#assessment-panel');if(!panel)return;if(!panel.querySelector('.assessment-help'))panel.innerHTML='<p class="note assessment-help">Scores the current snapshot, records policy decisions, and applies verified safe removals to a saved copy.</p><ol class="phase-rail" hidden></ol><p id="assessment-outcome"></p><p class="note" id="assessment-elapsed"></p><div id="assessment-retry"></div>';const view=visibleAssessment();const rail=panel.querySelector('.phase-rail');const phases=view?.phases||[];rail.hidden=!phases.length;phases.forEach((phase,index)=>{let item=rail.children[index];if(!item){item=document.createElement('li');item.innerHTML='<span class="phase-name"></span><span class="phase-meta"></span>';rail.append(item);}const status=phase.status||'pending';if(item.dataset.status!==status)item.dataset.status=status;const name=item.querySelector('.phase-name');if(name.textContent!==phase.label)name.textContent=phase.label;const meta=item.querySelector('.phase-meta');const count=phase.count==null?'':Number(phase.count).toLocaleString();if(meta.textContent!==count)meta.textContent=count;});while(rail.children.length>phases.length)rail.lastChild.remove();const outcome=$('#assessment-outcome');const message=assessmentMessage(view);if(outcome.textContent!==message)outcome.textContent=message;const elapsed=$('#assessment-elapsed');const last=view?.completed_at?`Last run ${String(view.completed_at).replace('T',' ').slice(0,19)}`:'';if(elapsed.textContent!==last)elapsed.textContent=last;const retry=$('#assessment-retry');const showRetry=!!(view&&['failed','stale','cancelled','interrupted'].includes(view.status));if(showRetry&&!retry.querySelector('button')){retry.innerHTML='<button class="btn" type="button" id="retry-assessment">Try again</button>';$('#retry-assessment').onclick=startRefresh;}else if(!showRetry)retry.replaceChildren();}
function scheduleAssessment(){clearTimeout(assessmentTimer);assessmentTimer=setTimeout(pollAssessment,700);}
async function pollAssessment(){assessmentTimer=0;if(!watchedRun||!['queued','running','cancelling'].includes(watchedRun.status))return;try{const current=await localJson('/api/assessments/current');const view=current.active?.id===watchedRun.id?current.active:current.latest?.id===watchedRun.id?current.latest:null;if(!view){scheduleAssessment();return;}watchedRun=view;if(['queued','running','cancelling'].includes(view.status)){paintAssessment();scheduleAssessment();return;}if(view.status==='succeeded'){announceRun=view;overview=null;toast(assessmentSentence(view.summary));render();return;}paintAssessment();toast(assessmentMessage(view));}catch{if(watchedRun&&['queued','running','cancelling'].includes(watchedRun.status))scheduleAssessment();}}
async function startRefresh(){const button=$('#refresh-scores');if(button){button.disabled=true;button.textContent='Running assessment';}const retry=$('#retry-assessment');if(retry)retry.disabled=true;try{const view=await localJson('/api/assessments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID()})});watchedRun=view;if(view.status==='succeeded'){announceRun=view;overview=null;toast(assessmentSentence(view.summary));render();return;}if(['queued','running','cancelling'].includes(view.status)){paintAssessment();scheduleAssessment();return;}paintAssessment();}catch(error){if(error.status===409){try{const current=await localJson('/api/assessments/current');if(current.active){watchedRun=current.active;paintAssessment();scheduleAssessment();return;}}catch{/* keep the refusal visible */}}paintAssessment();const outcome=$('#assessment-outcome');if(outcome)outcome.textContent=error.message||'The refresh could not start.';}}
function bindAssessment(){const button=$('#refresh-scores');if(button)button.onclick=startRefresh;const active=overview?.assessment?.active;if(active&&['queued','running','cancelling'].includes(active.status)&&(!watchedRun||!['queued','running','cancelling'].includes(watchedRun.status)))watchedRun=active;if(watchedRun&&['queued','running','cancelling'].includes(watchedRun.status))scheduleAssessment();paintAssessment();}
function changedCount(summary,key,value){const before=summary?.initial_counts?.[key],after=summary?.final_counts?.[key];const changed=before!=null&&after!=null&&before!==after;return `<dd${changed?' class="changed"':''}>${Number(value).toLocaleString()}</dd>`;}
const source=s=>s.type==='group'?`${s.group_id} → ${s.role_id}`:s.type==='role'?s.role_id:s.type==='temporary'?`Temporary${s.expired==='yes'?' · expired':''}`:human(s.type||'grant');
const initials=n=>String(n).split(/[\s_-]/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function preferred(i){const rows=i.permissions||[];if(i.showcase==='quarterly-recovery')return rows.find(r=>r.action==='db:Restore'&&r.in_workflow)||rows[0];if(i.showcase==='role-transfer')return rows.find(r=>r.excess&&r.action==='db:Write'&&r.sensitivity==='critical')||rows[0];if(i.showcase==='excess-service')return rows.find(r=>r.action==='secrets:Get'&&r.sources?.some(s=>s.type==='direct'))||rows[0];return rows.find(r=>r.outcome==='remove')||rows[0];}
function reason(p){const last=p.last_used_days==null?'No usage log is available.':`Last used ${p.last_used_days} days ago.`;return `${last} ${p.outcome==='retain'&&p.in_workflow?'A documented workflow still requires this permission. ':''}${p.removal_probe?.reason||'Inspect the documented need and available context before making a change.'}`;}
function options(values,current,all='All'){return `<option value="">${all}</option>`+values.map(v=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(human(v))}</option>`).join('');}
function pager(total,offset,limit){return `<div class="pager"><span>${total?`${offset+1}-${Math.min(offset+limit,total)}`:'0'} of ${total.toLocaleString()} results</span><div><button class="btn quiet" data-page="${Math.max(0,offset-limit)}" ${offset===0?'disabled':''}>Previous</button><button class="btn quiet" data-page="${offset+limit}" ${offset+limit>=total?'disabled':''}>Next</button></div></div>`;}
function bindFilters(r){const f=$('#filters');if(f)f.onsubmit=e=>{e.preventDefault();go(r.page,{...Object.fromEntries(new FormData(f)),offset:0});};const clear=$('[data-reset]');if(clear)clear.onclick=()=>go(r.page,r.page==='directory'?{collection:r.collection||'people'}:{});main.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(r.page,{...r,offset:b.dataset.page}));}
async function render(){const token=++epoch;controller?.abort();controller=new AbortController();simController?.abort();simToken++;sim=null;proposal=null;const r=route(),top=titles[r.page]?r.page:'overview';$('#nav').innerHTML=Object.entries(titles).map(([k,v])=>`<a class="nav-link ${top===k?'active':''}" href="${href(k)}" ${top===k?'aria-current="page"':''}>${v}</a>`).join('');document.title=`${titles[top]} - EntitleGuard`;$('#shell-export').hidden=false;main.innerHTML='<div class="skeleton" aria-label="Loading view" aria-busy="true"></div>';try{if(!overview){overview=await api('/api/overview');overview.run={...overview.run,...await api('/api/run')};}if(token!==epoch)return;const warning=$('#run-warning');warning.hidden=!overview.run?.restore_warning;warning.textContent=overview.run?.restore_warning?`The previous experiment could not be restored. The baseline snapshot is active. ${overview.run.restore_warning}`:'';const datasetId=overview.run?.dataset_id||'synthetic enterprise';$('#snapshot').textContent=`As of ${overview.overview.as_of}. Dataset ${datasetId.length>16?datasetId.slice(0,16):datasetId}`;$('#snapshot').title=datasetId;if(r.id&&top==='findings')await investigation(r,token);else await ({overview:viewOverview,findings:viewFindings,directory:viewDirectory,evaluation:viewEvaluation,decisions:viewDecisions}[top])(r,token);if(token===epoch)bindAssessment();}catch(e){if(e.name==='AbortError'||token!==epoch)return;main.innerHTML=heading('This view could not load','Your data has not been changed.')+`<div class="error" role="alert">${esc(e.message)}</div><p class="note" style="margin-top:18px">Check that the local console is running, then try again.</p><button class="btn" id="retry" style="margin-top:15px">Try again</button>`;$('#retry').onclick=render;}}
async function viewOverview(r,token){
  const s=overview.overview;
  const demos=await Promise.all((overview.demos||[]).map(d=>api(`/api/identities/${encodeURIComponent(d.id)}`)));
  if(token!==epoch)return;
  const stories={
    'role-transfer':['Access outlived the role','Follow a legacy group from an old engineering role into a critical database.'],
    'quarterly-recovery':['Rare use, essential access','A quarterly restore looks dormant. The recovery workflow tells a different story.'],
    'excess-service':['A service account with too much reach','Keep the landing-bucket duty. Investigate unrelated credentials and IAM access.']
  };
  const wash=announceRun?.summary;announceRun=null;
  main.innerHTML=heading('Access review',`Snapshot ${s.as_of}`,`${refreshAction()}<a class="btn" href="#findings">Review findings</a>`)+assessmentPanel()+`
    <section class="snapshot-summary" aria-labelledby="scope-title">
      <div class="section-head"><h2 id="scope-title">In this snapshot</h2><a class="evaluation-link" href="#evaluation">Inspect the evaluation</a></div>
      <dl class="scope-list">
          <div><dt>Identities in scope</dt><dd>${s.identities.toLocaleString()}</dd><p>${s.employees} employees, ${s.contractors??0} contractors, ${s.service_accounts} service accounts</p></div>
          <div><dt>With role drift</dt>${changedCount(wash,'drift_cases',s.drift_cases)}<p>Catalogued access outside current duty</p></div>
          <div><dt>Sensitive excess grants</dt>${changedCount(wash,'sensitive_excess_paths',s.sensitive_excess_paths)}<p>High or critical resource exposure</p></div>
          <div><dt>Need human review</dt>${changedCount(wash,'pending_reviews',s.pending_reviews)}<p>Unresolved evidence, not safe removal</p></div>
        </dl>
    </section>
    <section class="review-queue" aria-labelledby="queue-title">
      <div class="section-head"><h2 id="queue-title">Priority review queue</h2><a href="#findings">All findings</a></div>
      ${findingsTable((overview.findings||[]).slice(0,5))}
    </section>
    <section class="case-section" aria-labelledby="cases-title">
      <div class="section-head"><h2 id="cases-title">Case studies</h2></div>
      <div class="case-register">${demos.map(({identity:i})=>{
        const p=preferred(i),copy=stories[i.showcase]||['Investigate access',i.responsibility];
        return `<a class="case-entry" href="${caseHref(i.id,p?.permission_id)}"><span class="case-person"><strong>${esc(i.name)}</strong><span class="mono">${esc(i.id)}</span></span><span class="case-description"><strong>${esc(copy[0])}</strong><p>${esc(copy[1])}</p></span>${chip(p?.outcome||'review')}<span class="case-open">Open case</span></a>`;
      }).join('')}</div>
    </section>
    <details class="method-note"><summary>About this snapshot</summary><p>Every recommendation joins role documentation, activity, peer context, and workflow requirements. Simulation tests the change before you decide.</p><dl><div><dt>Analysis</dt><dd>Local heuristic</dd></div><div><dt>Dataset date</dt><dd>${esc(s.as_of)}</dd></div><div><dt>Live access changes</dt><dd>Disabled by design</dd></div></dl></details>`;
}
function findingsTable(rows){return `<div class="table-wrap"><table class="findings-table"><thead><tr><th>Identity</th><th>Permission / resource</th><th>Recommendation</th><th class="num">Severity score</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><a class="row-open" href="${caseHref(r.identity_id,r.permission_id)}">${esc(r.name||r.identity_id)}</a><small>${esc(r.identity_id)} · ${esc(r.role_title)}</small></td><td>${esc(r.action)}<small>${esc(r.resource_name)}</small></td><td>${chip(r.outcome)}<small>${esc(human(r.scenario))}</small>${r.evidence_complete!==undefined?`<small>${r.evidence_complete?'Usage log available':'Usage log missing'} · ${esc(human(r.review_status))}</small>`:''}</td><td class="num">${num(r.severity)}</td><td><a href="${caseHref(r.identity_id,r.permission_id)}" aria-label="Investigate ${esc(r.name)} ${esc(r.action)}">Review</a></td></tr>`).join('')}</tbody></table></div>`;}
async function viewFindings(r,token){const offset=Math.max(0,Number(r.offset)||0),limit=20;const data=await api('/api/findings?'+new URLSearchParams({q:r.q||'',outcome:r.outcome||'',kind:r.kind||'',sort:r.sort||'severity',department:r.department||'',severity:r.severity||'',evidence:r.evidence||'',review_status:r.review_status||'',limit,offset}));const departments=await api('/api/catalog?collection=departments&limit=200');if(token!==epoch)return;main.innerHTML=heading('Findings','A recommendation is a starting point. Open a grant to inspect its evidence.',refreshAction())+assessmentPanel()+`<form id="filters" class="tools"><label class="field grow">Search findings<input name="q" value="${esc(r.q||'')}" type="search" placeholder="Name, identity, action, or resource"></label><label class="field">Recommendation<select name="outcome">${options(['remove','reduce','retain','temporary','review'],r.outcome)}</select></label><label class="field">Identity kind<select name="kind">${options(['employee','contractor','service'],r.kind)}</select></label><label class="field">Sort by<select name="sort"><option value="severity" ${r.sort!=='name'?'selected':''}>Highest severity</option><option value="name" ${r.sort==='name'?'selected':''}>Identity name</option></select></label><label class="field">Severity score<select name="severity"><option value="">All scores</option>${[['high','High, 0.70 and above'],['medium','Medium, 0.40-0.69'],['low','Low, under 0.40']].map(([v,t])=>`<option value="${v}" ${r.severity===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="field">Usage evidence<select name="evidence"><option value="">All usage evidence</option><option value="missing" ${r.evidence==='missing'?'selected':''}>Usage log missing</option><option value="complete" ${r.evidence==='complete'?'selected':''}>Usage log available</option></select></label><label class="field">Review record<select name="review_status">${options(['recorded','unrecorded'],r.review_status)}</select></label><label class="field">Department<select name="department"><option value="">All departments</option>${departments.items.map(d=>`<option value="${esc(d.id)}" ${r.department===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><button class="btn primary">Apply filters</button></form>${data.items?.length?findingsTable(data.items):empty('No findings match','Try a broader search or another recommendation.')}${pager(data.total||0,offset,limit)}`;bindFilters(r);}
async function investigation(r,token){const [payload,decisionPage]=await Promise.all([api(`/api/identities/${encodeURIComponent(r.id)}`),api('/api/decisions?'+new URLSearchParams({identity_id:r.id,limit:'200'}))]);if(token!==epoch)return;const i=payload.identity,p=i.permissions.find(x=>x.permission_id===r.permission)||preferred(i),section=['evidence','paths','history','simulation'].includes(r.section)?r.section:'evidence';history.replaceState(null,'',href('findings',{id:i.id,permission:p?.permission_id,section}));main.innerHTML=`<div class="case-tools">${refreshAction()}</div>${assessmentPanel()}<div class="breadcrumb"><a href="#findings">Findings</a><span>/</span><span>${esc(i.id)}</span><span>/</span><span>${esc(human(section))}</span></div><div class="identity-head"><span class="avatar">${esc(initials(i.name))}</span><div><h1>${esc(i.name)}</h1><p>${esc(i.role_title)}, ${esc(i.team)}</p><p class="mono">${esc(i.id)}</p></div><div class="identity-status"><span class="chip">${esc(i.kind||'identity')} · ${esc(i.status)}</span><p>Drift ${num(i.drift?.drift)} · ${i.permissions.length} effective grants</p></div></div><nav class="tabs" aria-label="Investigation sections">${[['evidence','Evidence'],['paths','Access paths'],['history','History'],['simulation','Simulation']].map(([k,v])=>`<a href="${caseHref(i.id,p?.permission_id,k)}" class="${section===k?'active':''}" ${section===k?'aria-current="page"':''}>${v}</a>`).join('')}</nav><div id="case-content"></div>`;const node=$('#case-content');if(!p){node.innerHTML='<p>This identity has no effective permissions.</p>';return;}if(section==='paths')return paths(i,p,node,token);if(section==='history')return historyView(i,node);if(section==='simulation')return simulationView(i,p,node,token);const rank={remove:0,reduce:1,review:2,temporary:3,retain:4},sorted=[...i.permissions].sort((a,b)=>(rank[a.outcome]??9)-(rank[b.outcome]??9)||b.severity-a.severity);node.innerHTML=`<div class="workspace"><aside class="grant-list"><div class="list-title">Effective permissions <span class="mono">${i.permissions.length}</span></div>${sorted.map(x=>`<a class="grant ${x.permission_id===p.permission_id?'active':''}" href="${caseHref(i.id,x.permission_id)}" style="text-decoration:none;color:inherit" ${x.permission_id===p.permission_id?'aria-current="true"':''}>${chip(x.outcome)}<strong>${esc(x.action)}</strong><small>${esc(x.resource_name)}</small><small>${esc(x.sensitivity)} · ${x.last_used_days==null?'no usage log':x.last_used_days+' days since use'}</small></a>`).join('')}<label class="sr-only" for="grant-select">Select permission</label><select class="mobile-grant-select" id="grant-select" style="display:none">${sorted.map(x=>`<option value="${esc(x.permission_id)}" ${x.permission_id===p.permission_id?'selected':''}>${esc(x.action)} · ${esc(x.resource_name)} · ${esc(x.outcome)}</option>`).join('')}</select></aside><article class="inspector">${evidence(i,p,payload,decisionPage.items||[])}</article></div>`;$('#grant-select').onchange=e=>go('findings',{id:i.id,permission:e.target.value,section});$('#ask-live').onclick=()=>askLive(i,p,token);}
function evidence(i,p,payload,decisions=[]){const facts=[['Access source',(p.sources||[]).map(source).join('; ')||'No source recorded'],['Workflow requirement',p.in_workflow?`Required${p.workflow_cadence?' · '+p.workflow_cadence:''}`:'Not in a documented workflow'],['Role documentation',p.on_role_document?'Listed for current role':'Outside current role document'],['Usage evidence',p.last_used_days==null?'Missing. Absence is not proof of disuse':`${p.last_used_days} days ago, ${p.use_count_180d??'unknown'} uses in 180 days`],['Sensitivity',`${p.sensitivity}${p.privileged?' · privileged action':''}`],['Approved exception',p.in_exception?'Active exception':'No active exception'],['Peer prevalence',`${num(p.peer_prevalence*100,0)}% of training peers in this role`],['Requirement class',human(p.requirement_class)]];const grantRows=(decisions||[]).filter(row=>row.permission_id===p.permission_id||row.change?.permission_id===p.permission_id||(row.simulation?.removed_permission_ids||[]).includes(p.permission_id));const decisionBlock=`<div class="grant-decisions"><h3>Decisions on this grant</h3>${grantRows.length?grantRows.slice(0,6).map(row=>`<p>${chip(row.decision)} ${esc(row.actor_type==='machine'||row.source==='automatic_policy'?(row.analyst||'EntitleGuard policy'):(row.analyst||'Analyst'))} · ${esc(row.applied_in_simulation?'Applied in the saved copy':'Not applied')}</p><p class="note">${esc(row.rationale||'')}</p>`).join(''):'<p class="note">No decision is recorded for this grant. Refresh risk scores, or test a change and record one.</p>'}</div>`;return `<div class="grant-title"><div><h2>${esc(p.action)}</h2><p class="muted">${esc(p.resource_name)}</p></div>${chip(p.outcome)}</div><div class="recommendation"><h3>${{remove:'Remove excess access',retain:'Keep this permission',reduce:'Narrow the permission',temporary:'Preserve the approved exception',review:'Resolve the missing evidence'}[p.outcome]||'Review this permission'}</h3><p>${esc(reason(p))}</p><a class="btn primary" href="${caseHref(i.id,p.permission_id,'simulation')}">Test a change ${icon('arrow')}</a> <a class="btn quiet" href="${caseHref(i.id,p.permission_id,'paths')}">Trace access</a></div><dl class="evidence-grid">${facts.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${decisionBlock}<div class="baseline-list"><h3>Why context changes the answer</h3>${[['90-day unused',p.last_used_days==null||p.last_used_days>90?'remove':'retain','Uses recency alone; missing logs also trigger removal.'],['Role whitelist',p.on_role_document?'retain':'remove','Checks whether the current role document lists this permission.'],['EntitleGuard',p.outcome,p.removal_probe?.reason||'Combines documented need and context.']].map(([k,v,n])=>`<div class="baseline-line"><span>${k}<small>${esc(n)}</small></span>${chip(v)}</div>`).join('')}</div><div class="model-note"><h3>Local heuristic judgment</h3><p>Scores are hand-set indicators, not calibrated probabilities. Optional hosted judgment is separate from the offline evaluation.</p>${score('Fits current duty',p.jev?.answers?.role_consistency?.noul)}${score('Rare use plausible',p.jev?.answers?.rare_usage_plausible?.noul)}<button id="ask-live" class="btn">${overview.run?.provider==='heuristic'?'Refresh local judgment':'Ask live Jev'}</button><div id="live-result" role="status"></div></div><details><summary>Inspect provenance and raw evidence</summary><p>Snapshot <span class="mono">${esc(payload.dataset_id||overview.run?.dataset_id||'current')}</span>. The policy outcome and analyst decision are separate.</p><pre class="raw">${esc(JSON.stringify(p,null,2))}</pre></details>`;}
const score=(label,v)=>`<div class="score-row"><span>${label}</span><div class="track"><div class="fill" style="width:${Math.max(0,Math.min(1,v||0))*100}%"></div></div><span class="num">${num(v)}</span></div>`;
async function askLive(i,p,token){const b=$('#ask-live'),n=$('#live-result');b.disabled=true;b.textContent='Requesting judgment…';n.innerHTML=overview.run?.provider==='heuristic'?'<p>Refreshing the local heuristic. No external request is made.</p>':'<p>Contacting the configured provider. Offline evidence remains available.</p>';try{const d=await post(`/api/identities/${encodeURIComponent(i.id)}/jev`,{permission_id:p.permission_id});if(token!==epoch)return;const j=d.judgment||d.heuristic;n.innerHTML=`<p><strong>${esc(j?.provider||'Judgment returned')}</strong> · ${esc(j?.model||'Local heuristic')}</p>${j?.error?`<p class="error">${esc(j.error)}</p>`:''}${j?score('Fits current duty',j.answers?.role_consistency?.noul)+score('Rare use plausible',j.answers?.rare_usage_plausible?.noul):'<p>No hosted result is available.</p>'}`;}catch(e){if(e.name!=='AbortError'&&token===epoch)n.innerHTML=`<p class="error">${esc(e.message)}. You can retry; local evidence remains available.</p>`;}finally{if(b.isConnected){b.disabled=false;b.textContent=overview.run?.provider==='heuristic'?'Refresh local judgment':'Ask live Jev again';}}}
async function paths(i,p,node,token){const g=await api(`/api/identities/${encodeURIComponent(i.id)}/graph`);if(token!==epoch)return;let selected=p.permission_id,zoom=1;const labels=new Map(g.nodes.map(n=>[n.id,n.label||n.id])),kinds=['identity','group','role','resource'],positions={},counts={};g.nodes.forEach(n=>{const kind=kinds.includes(n.kind)?n.kind:'resource',index=counts[kind]||0;positions[n.id]={x:kinds.indexOf(kind)*230+15,y:55+index*67};counts[kind]=index+1;});const height=Math.max(310,...Object.values(counts).map(n=>n*67+80));node.innerHTML=`<div class="section-head"><div><h2>How access reaches the resource</h2><p>Permission-aware source chains from the current snapshot.</p></div></div><div class="graph-layout"><section><div class="graph-surface"><div class="graph-toolbar"><span>Selected permission highlighted</span><div><button id="zoom-out" aria-label="Zoom out">−</button><button id="zoom-in" aria-label="Zoom in">+</button><button id="fit">Fit</button></div></div><div class="graph-scroll" id="graph"></div></div><div class="legend"><span>Selected path</span><span>Other access</span></div><p class="note" style="margin-top:16px">Use the path list for full labels and keyboard navigation. Dashed paths indicate denied access when present.</p></section><aside><h3 style="margin-bottom:12px">Permission paths</h3><div class="path-list" id="paths"></div></aside></div>`;
function draw(){const chosen=g.paths.filter(x=>x.permission_id===selected),hot=new Set(chosen.flatMap(x=>x.path));const lines=g.edges.map(e=>{const a=positions[e.source],b=positions[e.target];if(!a||!b)return '';const on=chosen.some(path=>path.path.some((id,index)=>index>0&&id===e.target&&path.path[index-1]===e.source))&&(!e.permission_id||e.permission_id===selected);return `<path class="graph-edge ${on?'hot':''} ${e.denied?'denied':''}" d="M${a.x+175},${a.y+21} C${a.x+205},${a.y+21} ${b.x-30},${b.y+21} ${b.x},${b.y+21}"><title>${esc(e.action||e.relation||'membership')}</title></path>`;}).join('');const nodes=g.nodes.map(n=>{const a=positions[n.id],label=String(n.label||n.id);return `<g><title>${esc(label)}</title><rect class="graph-node ${hot.has(n.id)?'hot':''}" x="${a.x}" y="${a.y}" width="175" height="43" rx="5"/><text x="${a.x+10}" y="${a.y+26}">${esc(label.length>25?label.slice(0,23)+'…':label)}</text></g>`;}).join('');$('#graph').innerHTML=`<svg role="img" aria-label="Access graph for ${esc(i.name)}. Full paths available in adjacent list." viewBox="0 0 900 ${height}" style="width:${zoom*100}%">${kinds.map((k,index)=>`<text class="graph-label" x="${index*230+15}" y="23">${esc(human(k))}</text>`).join('')}${lines}${nodes}</svg>`;$('#paths').innerHTML=g.paths.length?g.paths.map(path=>`<button class="${path.permission_id===selected?'active':''}" data-path="${esc(path.permission_id)}" aria-pressed="${path.permission_id===selected}"><strong>${esc(path.action)} · ${esc(path.resource_name)}</strong><small>${esc(path.path.map(id=>labels.get(id)||id).join(' → '))}</small><small>${path.denied?'Denied, not effective':path.excess?'Outside documented need':'Documented or contextual access'} · ${esc(path.sensitivity)}</small></button>`).join(''):'<p class="note">No resource paths recorded.</p>';main.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{selected=b.dataset.path;history.replaceState(null,'',caseHref(i.id,selected,'paths'));main.querySelectorAll('.tabs a').forEach(a=>{const section=a.hash.split('section=')[1];a.href=caseHref(i.id,selected,section||'evidence');});draw();});}draw();$('#zoom-in').onclick=()=>{zoom=Math.min(2,zoom+.25);draw();};$('#zoom-out').onclick=()=>{zoom=Math.max(.75,zoom-.25);draw();};$('#fit').onclick=()=>{zoom=1;draw();};}
function historyView(i,node){const d=i.drift,points=[...(d.timeline||[])],last=points.at(-1);if(!last||last.granted!==d.granted||last.drift!==d.drift||last.role_title!==i.role_title)points.push({date:overview.overview.as_of,role_title:i.role_title,granted:d.granted,needed:d.needed,drift:d.drift,current:true});node.innerHTML=`<div class="section-head"><div><h2>Role changes leave an access trail.</h2><p>Drift is access outside documented need, not inactivity.</p></div></div><p class="note">Historical points use stored role snapshots. Current access appears separately when it differs from the last event.</p><div class="timeline">${points.map((p,index)=>`<article class="history-event"><time>${esc(p.date)}</time><div><h3>${esc(p.role_title)}${p.current?' · current snapshot':''}</h3><p class="note">${p.granted} effective grants · ${p.needed} documented needs</p>${index&&points[index-1].role_title!==p.role_title?`<p class="note" style="margin-top:8px">Role changed from ${esc(points[index-1].role_title)}. Existing sources may continue granting access.</p>`:''}<div class="track" style="margin-top:12px;max-width:420px"><div class="fill" style="width:${Math.max(0,Math.min(1,p.drift))*100}%"></div></div></div><div class="drift-value">${num(p.drift)}<small>drift score</small></div></article>`).join('')}</div><div class="notice">${esc(i.responsibility)} Current groups: ${esc([...new Set(i.permissions.flatMap(p=>(p.sources||[]).filter(s=>s.type==='group').map(s=>s.group_id)))].join(', ')||'none recorded')}.</div>`;}
function simulationView(i,p,node,token){const proposals=[...(i.proposals||[])];if(!proposals.some(x=>x.change?.type==='remove_permission'&&x.change.permission_id===p.permission_id))proposals.push({title:`Test removing ${p.action}`,change:{type:'remove_permission',permission_id:p.permission_id},counterfactual:true});node.innerHTML=`<div class="section-head"><div><h2>Simulate a change</h2><p>Simulation copies the model. Recording a decision never changes live access.</p></div></div><div class="simulation-layout"><aside><h3 style="margin-bottom:14px">Choose a proposal</h3><div class="proposals">${proposals.map((x,index)=>`<button class="proposal" data-proposal="${index}"><strong>${esc(x.title)}</strong><small>${esc(human(x.change?.type))}${x.counterfactual?' · counterfactual test':''}</small></button>`).join('')}</div></aside><section id="simulation-result"><div class="empty"><h3>Choose a change to test</h3><p>Inspect removed access and workflow impact before accepting, rejecting, or deferring the proposal.</p></div></section></div>`;main.querySelectorAll('[data-proposal]').forEach(b=>b.onclick=()=>runSimulation(i,proposals[Number(b.dataset.proposal)],b,token));}
const listItems=(items,text)=>items?.length?`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p class="note" style="margin-top:8px">${text}</p>`;
async function runSimulation(i,selected,button,token){const request=++simToken;simController?.abort();simController=new AbortController();sim=null;proposal=selected;main.querySelectorAll('[data-proposal]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});const target=$('#simulation-result');target.innerHTML='<div class="skeleton" aria-label="Simulating proposal" aria-busy="true"></div><p class="note" style="margin-top:12px">Testing workflows against a copy of the access model…</p>';try{const result=await post('/api/simulate',{identity_id:i.id,change:selected.change},simController.signal);if(token!==epoch||request!==simToken||proposal!==selected)return;sim=result;const label=id=>{const x=i.permissions.find(x=>x.permission_id===id);return x?`${x.action} · ${x.resource_name}`:id;};target.innerHTML=`<div class="verdict ${result.safe_to_remove?'safe':'unsafe'}"><h2>${result.safe_to_remove?'Safe in this simulated snapshot':'Removal is not verified safe'}</h2><p>${esc(result.reason)}</p></div><h3>What changes</h3><p class="note" style="margin-top:7px">${result.removed_permission_ids?.length?result.removed_permission_ids.length+' effective permission(s) removed.':'No effective permissions are removed by this proposal.'}</p><ul style="font-size:.82rem;padding-left:20px">${(result.removed_permission_ids||[]).map(id=>`<li>${esc(label(id))}</li>`).join('')}</ul><div class="comparison"><section><h3>Sensitive access before</h3>${listItems(result.critical_before,'No high or critical resource.')}</section><section><h3>Sensitive access after</h3>${listItems(result.critical_after,'No high or critical resource remains.')}</section></div><h3 style="margin-bottom:12px">Workflow preservation</h3>${result.workflows?.length?`<div class="table-wrap"><table><thead><tr><th>Workflow</th><th>Before</th><th>After</th></tr></thead><tbody>${result.workflows.map(w=>`<tr><td>${esc(w.name)}<small>${esc(w.cadence)}</small></td><td>${esc(w.before)}</td><td>${chip(w.after==='allowed'?'safe':w.after==='broken'?'reject':w.after)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="note">No role-bound workflow exists in the model. This does not establish that all real duties are known.</p>'}<form class="decision-form" id="decision-form"><h3>Record your decision</h3><p class="note">The analyst decision is separate from the engine recommendation. No access is applied.</p><div class="fields"><label class="field">Decision<select name="decision" required><option value="">Choose a decision</option><option value="accept" ${result.safe_to_remove?'':'disabled'}>Accept proposal${result.safe_to_remove?'':' (unsafe)'}</option><option value="reject">Reject proposal</option><option value="defer">Defer for more evidence</option></select></label><label class="field">Analyst<input name="analyst" required value="Vishnu" minlength="2" maxlength="100" autocomplete="name"></label><label class="field full">Rationale<textarea name="rationale" required minlength="8" maxlength="3000" placeholder="Explain the evidence behind your decision (at least 8 characters)."></textarea></label></div><button class="btn primary" id="record" ${result.simulation_id?'':'disabled'}>Record decision</button><p class="note" id="decision-status" role="status" style="margin-top:10px">${result.safe_to_remove?'Ready for analyst review.':'Accept is unavailable because this simulation did not establish a safe removal.'}</p><details style="margin-top:17px;font-size:.75rem"><summary>Simulation provenance</summary><p class="mono" style="margin-top:8px">Simulation ${esc(result.simulation_id||'unavailable')}<br>Dataset ${esc(result.dataset_id||'current')}<br>${esc(JSON.stringify(selected.change))}</p></details></form>`;$('#decision-form').onsubmit=e=>{e.preventDefault();recordDecision(result,request,token,e.currentTarget);};}catch(e){if(e.name!=='AbortError'&&token===epoch&&request===simToken)target.innerHTML=`<div class="error" role="alert">Simulation failed: ${esc(e.message)}</div><p class="note" style="margin-top:12px">Choose the proposal again to retry. A completed simulation is required before recording.</p>`;}}
async function recordDecision(result,request,token,form){if(sim!==result||request!==simToken||token!==epoch)return;const b=$('#record'),status=$('#decision-status'),values=Object.fromEntries(new FormData(form));if(values.decision==='accept'&&!result.safe_to_remove)return;b.disabled=true;const key=form.dataset.key||crypto.randomUUID();form.dataset.key=key;try{await post('/api/decisions',{simulation_id:result.simulation_id,...values,idempotency_key:key});if(token!==epoch||request!==simToken)return;status.innerHTML='Decision recorded. Access was not changed. <a href="#decisions">View history</a>';b.textContent='Decision recorded';form.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=true);toast('Decision recorded with its simulation and dataset.');}catch(e){if(e.name!=='AbortError'&&token===epoch&&request===simToken){status.textContent=`Could not record: ${e.message}. You can retry.`;b.disabled=false;}}}
const collections={people:['People',['id','name','kind','department','role_title','status']],departments:['Departments',['id','name','people','resources']],roles:['Roles',['id','title','department','duty','grant_count']],groups:['Groups',['id','name','purpose','department','roles']],resources:['Resources',['id','name','kind','sensitivity','environment','department']],permissions:['Permissions',['id','action','resource','sensitivity','requirement_class']],workflows:['Workflows',['id','name','cadence','roles','permissions']],exceptions:['Exceptions',['identity_id','permission_id','active','expires_on','reason']],usage:['Usage',['identity_id','permission_id','last_used_days','use_count_180d','outcome']],activity:['Activity',['identity_id','permission_id','action','days_ago','result']],labels:['Evaluation labels',['identity_id','permission_id','scenario','expected','y_unjustified']]};
async function viewDirectory(r,token){const c=collections[r.collection]?r.collection:'people',offset=Math.max(0,Number(r.offset)||0),limit=25,data=await api('/api/catalog?'+new URLSearchParams({collection:c,q:r.q||'',limit,offset}));if(token!==epoch)return;const rows=data.items||data[c]||[],columns=collections[c][1];main.innerHTML=heading('Directory','Explore identities, access sources, resources, and the evidence behind findings.')+`<nav class="collection-nav" aria-label="Directory collections">${Object.entries(collections).map(([k,[label]])=>`<a class="${k===c?'active':''}" href="${href('directory',{collection:k})}" ${k===c?'aria-current="page"':''}>${label}${data.counts?.[k]!=null?' '+Number(data.counts[k]).toLocaleString():''}</a>`).join('')}</nav><form class="tools" id="filters"><input name="collection" type="hidden" value="${c}"><label class="field grow">Search ${esc(collections[c][0].toLowerCase())}<input type="search" name="q" value="${esc(r.q||'')}" placeholder="Filter by name, ID, department, or value"></label><button class="btn primary">Search collection</button></form>${rows.length?`<div class="table-wrap"><table><thead><tr>${columns.map(k=>`<th>${esc(human(k))}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map((k,index)=>{const v=row[k],id=row.identity_id||(c==='people'?row.id:null);return `<td class="directory-cell">${index===0&&id?`<a href="${caseHref(id,row.permission_id)}">${esc(v)}</a>`:Array.isArray(v)?esc(v.join(', ')):typeof v==='object'&&v!==null?esc(JSON.stringify(v)):esc(v??'n/a')}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No directory records match','Search another value or clear this collection’s filters.')}${pager(data.total??rows.length,offset,limit)}`;bindFilters({...r,collection:c});}
async function viewEvaluation(r,token){const data=await api('/api/evaluation');if(token!==epoch)return;const run=data.run||{};const current=data.metrics||{};const benchmark=data.benchmark||{};const usingBenchmark=!(current.systems?.full&&current.labeled_cases>0);const m=usingBenchmark?benchmark:current;if(!m.systems?.full||!(m.labeled_cases>0)){$('#shell-export').hidden=true;const baseline=data.baseline_evaluation;const lead=[data.evaluation_note,baseline?`${baseline.label||'Original benchmark'}. ${baseline.reason||''}`.trim():''].filter(Boolean).join(' ');main.innerHTML=heading('Evaluation unavailable','There is no compatible completed evaluation for this active snapshot.')+`<div class="notice" role="status">${lead?`${esc(lead)} `:''}Evaluation artifacts are missing or do not match the current dataset and implementation. Detection quality, safety outcomes, and errors cannot be reported yet. ${data.evaluation_note?'Load the baseline snapshot to inspect the original benchmark.':'Start a Generate + evaluate dataset experiment below, then load its completed snapshot to inspect its results.'} Exports are available after a compatible evaluation completes.</div><section class="evaluation-section" id="experiments"></section>`;await experimentControls(token);return;}const systems=m.systems,full=systems.full,ci=full.confidence_intervals;main.innerHTML=heading('Evaluation','Reproducible offline results, with safety outcomes alongside detection quality.',report())+`${usingBenchmark?'<div class="notice" role="status">These figures are the original benchmark, saved before remediation. The active snapshot is a remediated copy, so this table is not a new accuracy result for that copy.</div>':''}`+`<div class="evaluation-intro"><div><h2>Heuristic evaluation · synthetic enterprise</h2><p>${esc(m.note||'These results use local deterministic judgment, not a hosted model.')} ${m.labeled_cases??'n/a'} labeled test grants. Five-way outcome matching is distinct from unjustified-access detection.</p><p>Scores are not calibrated probabilities. This benchmark does not establish production safety.</p></div><dl class="evaluation-meta"><div><dt>Dataset</dt><dd class="mono">${esc(usingBenchmark?(m._provenance?.dataset_id||'Original benchmark'):(run.dataset_id||'Current snapshot'))}${usingBenchmark&&run.dataset_id?` · active copy ${esc(String(run.dataset_id).slice(0,12))}`:''}</dd></div><div><dt>Seed / as of</dt><dd>${esc(run.seed??'n/a')} / ${esc(run.as_of||overview.overview.as_of)}</dd></div><div><dt>Analysis</dt><dd>${esc(human(run.analysis_status||'complete'))}</dd></div><div><dt>Policy version</dt><dd>${esc(run.policy_version||'n/a')}</dd></div></dl></div><div class="section-head"><h2>Detection and safety</h2><a href="/api/export?format=csv" style="font-size:.8rem">Per-case CSV</a></div><div class="table-wrap"><table><thead><tr><th>System</th><th class="num">Precision</th><th class="num">Recall</th><th class="num">F1</th><th class="num">False removals</th><th class="num">Workflows preserved</th><th class="num">Excess grants</th></tr></thead><tbody>${Object.keys(names).filter(k=>systems[k]).map(k=>{const x=systems[k],paths=x.sensitive_excess_grants||x.attack_paths||{};return `<tr class="${k==='full'?'emphasis':''}"><td>${names[k]}</td><td class="num">${num(x.precision,3)}</td><td class="num">${num(x.recall,3)}</td><td class="num">${num(x.f1,3)}</td><td class="num">${x.false_removals} / ${x.legitimate_cases??'n/a'}<small>${num(x.false_removal_rate*100,1)}%</small></td><td class="num">${num(x.workflow_preservation*100,1)}%</td><td class="num">${paths.before??'n/a'} → ${paths.after??'n/a'}</td></tr>`;}).join('')}</tbody></table></div><p class="note" style="margin-top:12px">False removals count removal of known-legitimate access. Harmful reductions and unresolved removals are reported separately. Minus context uses the same rule as 90-day unused.</p><div class="chart-row"><section><h2>Unjustified-access detection</h2><p class="note" style="margin-top:6px">F1 · higher is better</p><div class="bar-chart">${Object.keys(names).filter(k=>systems[k]).map(k=>`<div class="chart-line ${k==='full'?'full':''}"><span>${names[k]}</span><div class="track"><div class="fill" style="width:${systems[k].f1*100}%"></div></div><span class="num">${num(systems[k].f1,3)}</span></div>`).join('')}</div></section><section><h2>Safety in the test split</h2><p class="note" style="margin-top:6px">Observed outcomes, not a universal safety claim</p><dl class="evidence-grid"><div><dt>Known-legitimate removals</dt><dd>${full.false_removals??'n/a'} / ${full.legitimate_cases??'n/a'}</dd></div><div><dt>Unresolved removals</dt><dd>${full.unresolved_removals??'n/a'} / ${full.unresolved_cases??'n/a'}</dd></div><div><dt>Harmful reductions</dt><dd>${full.harmful_reductions??'n/a'}</dd></div><div><dt>Workflows preserved</dt><dd>${full.workflows?.preserved??'n/a'} / ${full.workflows?.eligible_before??'n/a'}</dd></div><div><dt>F1 confidence interval</dt><dd>${ci?.intervals?.f1?.map(x=>num(x,3)).join(' - ')||'Not available'}</dd></div><div><dt>Interval method</dt><dd>${esc(ci?.method||'No interval saved')}${ci?.clusters?' · '+ci.clusters+' identity clusters':''}</dd></div></dl></section></div>${full.confusion_matrix?confusion(full.confusion_matrix):''}<section class="evaluation-section"><div class="section-head"><h2>Scenario performance</h2><span class="note">EntitleGuard, test split</span></div><div class="table-wrap"><table><thead><tr><th>Scenario</th><th class="num">Labeled</th><th class="num">Exact matches</th><th class="num">False removals</th><th class="num">90-day false removals</th></tr></thead><tbody>${Object.entries(m.scenarios||{}).map(([k,x])=>`<tr><td>${esc(human(k))}</td><td class="num">${x.n}</td><td class="num">${x.full_correct}</td><td class="num">${x.full_false_removals}</td><td class="num">${x.unused90_false_removals}</td></tr>`).join('')}</tbody></table></div></section><section class="evaluation-section"><h2>Inspect the errors</h2><p class="note" style="margin:8px 0 17px">Incorrect five-way outcomes from the full system. Open an identity to inspect evidence.</p>${errorTable((m.predictions||[]).filter(p=>p.system==='full'&&!p.correct))}</section><section class="evaluation-section"><h2>Method and limits</h2><div class="notice">${(m.limitations||['Synthetic identities and documented duties do not capture a production directory.','Zero observed failures in a finite test set does not imply zero risk.','Hosted-model calls are optional and separate from these offline results.']).map(x=>`<p style="margin:7px 0">${esc(x)}</p>`).join('')}</div><details><summary>Metric definitions and run manifest</summary><pre class="raw" style="margin-top:14px">${esc(JSON.stringify({metric_definitions:m.metric_definitions,score_semantics:m.score_semantics,split_counts:m.split_counts,timings_ms:m.timings_ms,run},null,2))}</pre></details></section><section class="evaluation-section" id="experiments"></section><div class="head-actions" style="margin-top:28px"><a class="btn" href="/api/export?format=json">Export JSON bundle</a><a class="btn" href="/api/export?format=csv">Export predictions CSV</a></div>`;if(usingBenchmark)data.robustness=data.benchmark_robustness;renderValidation(data);await experimentControls(token);}
function confusion(matrix){const outcomes=['retain','remove','reduce','temporary','review'];return `<section class="evaluation-section"><h2>Five-outcome confusion matrix</h2><p class="note" style="margin:8px 0 17px">Rows: expected. Columns: predicted. Diagonal cells are exact matches.</p><div class="table-wrap"><table class="confusion"><thead><tr><th>Expected / predicted</th>${outcomes.map(x=>`<th>${human(x)}</th>`).join('')}</tr></thead><tbody>${outcomes.map(a=>`<tr><th>${human(a)}</th>${outcomes.map(b=>`<td style="${a===b?'background:#e2ebe1;color:#285d43':''}">${matrix[a]?.[b]??0}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function errorTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Identity / permission</th><th>Scenario</th><th>Expected</th><th>Predicted</th></tr></thead><tbody>${rows.map(p=>`<tr><td><a href="${caseHref(p.identity_id,p.permission_id)}">${esc(p.identity_id)}</a><small>${esc(p.permission_id)}</small></td><td>${esc(human(p.scenario))}</td><td>${chip(p.expected)}</td><td>${chip(p.predicted)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">No full-system outcome errors were observed in this test split. Read the limitations before generalizing.</div>';}
async function viewDecisions(r,token){const offset=Math.max(0,Number(r.offset)||0),limit=20,d=await api('/api/decisions?'+new URLSearchParams({q:r.q||'',decision:r.decision||'',actor:r.actor||'',limit,offset}));if(token!==epoch)return;const filtered=!!(r.q||r.decision||r.actor);main.innerHTML=heading('Decision history','A durable record of the proposal, the simulation, and the analyst’s reasoning.',report())+`<form id="filters" class="tools"><label class="field grow">Search records<input name="q" type="search" value="${esc(r.q||'')}" placeholder="Identity, analyst, or rationale"></label><label class="field">Decision<select name="decision">${options(['accept','reject','defer','apply','hold'],r.decision)}</select></label><label class="field">Recorded by<select name="actor"><option value="">All records</option><option value="human" ${r.actor==='human'?'selected':''}>Analyst</option><option value="machine" ${r.actor==='machine'?'selected':''}>EntitleGuard policy</option></select></label><button class="btn primary">Apply filters</button></form>${d.items?.length?`<div class="ledger">${d.items.map(x=>`<article class="ledger-entry"><time>${esc(String(x.created_at).replace('T',' ').slice(0,19))}</time><div><h3><a href="${caseHref(x.identity_id,x.permission_id,'evidence')}">${esc(x.identity_name||x.identity_id)}</a> <span class="mono">${esc(x.identity_id)}</span></h3><p>${esc(x.rationale)}</p><p class="note">${esc(x.analyst||'Analyst')} · ${x.actor_type==='machine'||x.source==='automatic_policy'?'Policy decision':'Analyst decision'} · ${x.applied_in_simulation?'Applied in the saved copy':'Not applied'}</p><details><summary>Proposal and provenance</summary><pre>${esc(JSON.stringify({decision_id:x.id,change:x.change,simulation_id:x.simulation_id,dataset_id:x.dataset_id,original_dataset_id:x.original_dataset_id,applied:x.applied,applied_in_simulation:x.applied_in_simulation,actor_type:x.actor_type||'human',run_id:x.run_id,policy_version:x.policy_version,simulation_outcome:x.simulation_outcome},null,2))}</pre></details></div>${chip(x.decision)}</article>`).join('')}</div>`:filtered?empty('No decisions in this view','Adjust the search, or record a decision from a finding.'):`<div class="empty"><h3>No decisions yet</h3><p>Refresh risk scores to record policy decisions, or open a finding and record an analyst decision.</p>${refreshAction()}</div>`}${pager(d.total||0,offset,limit)}`;bindFilters(r);}
async function experimentControls(token){const node=$('#experiments');node.innerHTML=`<h2>Run an experiment</h2><p class="note" style="margin-top:8px">Generate and evaluate a separate dataset, or run a multi-seed benchmark. Your active snapshot stays available until you explicitly load a completed run.</p><form id="job-form" class="tools"><label class="field">Experiment<select name="command"><option value="all">Generate + evaluate dataset</option><option value="benchmark">Multi-seed robustness benchmark</option></select></label><label class="field">Seed<input type="number" name="seed" min="0" max="2147483647" value="42" required style="width:120px"></label><label class="field">Snapshot date<input type="date" name="as_of" value="${esc(overview.overview.as_of)}" required></label><button class="btn primary" id="start-job">Start experiment</button><button class="btn quiet" type="button" id="baseline">Load baseline</button></form><div id="job-status" role="status"></div><div id="job-list"></div><div id="benchmark-result"></div>`;async function activate(id){try{await post('/api/run/activate',{job_id:id});if(token!==epoch)return;overview=null;toast('Active snapshot updated. Existing decisions remain in the ledger.');render();}catch(e){if(token===epoch)$('#job-status').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
async function refresh(){try{const d=await api('/api/jobs');if(token!==epoch)return;const pending=d.items.some(x=>['queued','running','cancelling'].includes(x.status));$('#start-job').disabled=pending;$('#job-list').innerHTML=d.items.length?`<div class="table-wrap"><table><thead><tr><th>Experiment</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${d.items.map(j=>`<tr><td>${j.command==='assess'?'Risk assessment':j.command==='all'?'Dataset + evaluation':'Robustness benchmark'}<small>Seed ${j.seed} · ${esc(j.as_of)}</small></td><td>${chip(j.status)}${d.selected_job_id===j.id?'<small>Active snapshot</small>':''}</td><td class="mono">${esc(j.created_at?.replace('T',' ').slice(0,19))}</td><td>${['queued','running'].includes(j.status)?`<button class="btn quiet" data-cancel="${esc(j.id)}">Cancel</button>`:''}${j.command==='benchmark'&&j.status==='succeeded'?`<button class="btn" data-benchmark="${esc(j.id)}">View benchmark results</button>`:''}${j.activatable?`<button class="btn" data-load="${esc(j.id)}" ${d.selected_job_id===j.id?'disabled':''}>Load snapshot</button>`:''}<details style="margin-top:8px"><summary>Run log</summary><pre class="raw">${esc(j.output||'No output yet.')}</pre>${j.output_truncated?'<p class="note">Output truncated by the server.</p>':''}</details></td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">No experiment runs yet. The baseline dataset is ready to inspect.</div>';node.querySelectorAll('[data-benchmark]').forEach(b=>b.onclick=()=>showBenchmark(b.dataset.benchmark,token));node.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>activate(b.dataset.load));node.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await post(`/api/jobs/${b.dataset.cancel}/cancel`,{});await refresh();}catch(e){if(token===epoch)$('#job-status').textContent=e.message;}});if(pending)setTimeout(()=>{if(token===epoch)refresh();},1800);}catch(e){if(e.name!=='AbortError'&&token===epoch)$('#job-status').innerHTML=`<div class="error">Experiment status could not load: ${esc(e.message)}</div>`;}}
$('#job-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));$('#start-job').disabled=true;try{await post('/api/jobs',{...values,seed:Number(values.seed)});if(token===epoch){toast('Experiment started in a separate run directory.');await refresh();}}catch(e){if(e.name!=='AbortError'&&token===epoch){$('#job-status').innerHTML=`<div class="error">${esc(e.message)}</div>`;$('#start-job').disabled=false;}}};$('#baseline').onclick=()=>activate(null);await refresh();}
$('#search-form').onsubmit=e=>{e.preventDefault();go('directory',{collection:'people',q:$('#global-q').value.trim()});};
$('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();$('#global-q').focus();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
render();
function renderValidation(data){const m=data.metrics?.systems?.full?data.metrics:(data.benchmark||{}),h=m.independent_holdout,b=data.robustness,target=$('#experiments');let html='';if(h)html+=`<section class="evaluation-section"><h2>Independent context fixtures</h2><p class="note" style="margin:8px 0 16px">${esc(h.kind)} · ${h.correct} / ${h.n} correct. ${esc(h.limitation)}</p><div class="table-wrap"><table><thead><tr><th>Fixture</th><th>Expected</th><th>Predicted</th><th>Match</th></tr></thead><tbody>${h.cases.map(x=>`<tr><td>${esc(human(x.case_id))}</td><td>${chip(x.expected)}</td><td>${chip(x.predicted)}</td><td>${x.correct?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div></section>`;html+=`<section class="evaluation-section"><h2>Varied-world robustness</h2>${b?`<p class="note" style="margin:8px 0 17px">${esc(b.note)}</p><div class="table-wrap"><table><thead><tr><th>Seed</th><th class="num">Test grants</th><th class="num">F1</th><th class="num">False removals</th><th class="num">Generation time</th></tr></thead><tbody>${b.runs.map(x=>`<tr><td>${x.seed}</td><td class="num">${x.labeled_cases}</td><td class="num">${num(x.full.f1,3)}</td><td class="num">${x.full.false_removals}</td><td class="num">${num(x.generation_ms,0)} ms</td></tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:13px">F1 mean ${num(b.summary?.f1?.mean,3)} · standard deviation ${num(b.summary?.f1?.stddev,3)} · range ${num(b.summary?.f1?.min,3)}-${num(b.summary?.f1?.max,3)}.</p>`:'<div class="notice">No compatible robustness suite is saved for this active snapshot. Run a multi-seed benchmark below. A benchmark remains separate from a generated dataset.</div>'}</section>`;target.insertAdjacentHTML('beforebegin',html);}
async function showBenchmark(id,token){const node=$('#benchmark-result');node.innerHTML='<div class="skeleton" aria-label="Loading benchmark results" aria-busy="true" style="margin-top:25px"></div>';try{const d=await api(`/api/jobs/${encodeURIComponent(id)}/results`);if(token!==epoch)return;const b=d.robustness;node.innerHTML=`<section class="evaluation-section"><h2>Completed benchmark results</h2><p class="note" style="margin:8px 0 17px">Separate experiment ${esc(id.slice(0,12))}. The active dataset has not changed. ${esc(b.note)}</p><div class="table-wrap"><table><thead><tr><th>Seed</th><th class="num">Test grants</th><th class="num">F1</th><th class="num">False removals</th><th class="num">Generation</th></tr></thead><tbody>${b.runs.map(x=>`<tr><td>${x.seed}</td><td class="num">${x.labeled_cases}</td><td class="num">${num(x.full.f1,3)}</td><td class="num">${x.full.false_removals}</td><td class="num">${num(x.generation_ms,0)} ms</td></tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:13px">F1 mean ${num(b.summary?.f1?.mean,3)} · standard deviation ${num(b.summary?.f1?.stddev,3)} · range ${num(b.summary?.f1?.min,3)}-${num(b.summary?.f1?.max,3)}.</p><details style="margin-top:15px"><summary>Full benchmark artifact</summary><pre class="raw">${esc(JSON.stringify(b,null,2))}</pre></details></section>`;node.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}catch(e){if(e.name!=='AbortError'&&token===epoch)node.innerHTML=`<div class="error" role="alert" style="margin-top:20px">Benchmark results unavailable: ${esc(e.message)}. Select View benchmark results to retry.</div>`;}}
